# IFR regulations and pilot qualifications: 14 CFR 61.3, 61.51, 61.57, 61.65, 91.103, 91.109, 91.123,
# 91.167, 91.169, 91.171, 91.187, 91.205, 91.211, 91.411, 91.413 (eCFR, current). ACS area I.A, II.C.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 3, "Instrument currency", "A pilot logged six approaches, holding and course tracking on January 20 and nothing since. Through what date may the pilot act as PIC under IFR?",
      ["July 31", "June 30", "July 20"],
      "61.57(c) looks back 6 calendar months before the month of the flight. A flight in July looks back to January, so the January tasks keep the pilot current through July 31."),
    S(1, 2, "Alternate requirement", "No alternate is needed when, from 1 hour before to 1 hour after the ETA, the destination is forecast to have at least:",
      ["2,000-foot ceiling and 3 SM", "1,000-foot ceiling and 3 SM", "2,000-foot ceiling and 5 SM"],
      "91.169(b) drops the alternate when the destination has a published approach and the forecast shows a ceiling of at least 2,000 feet and visibility of at least 3 SM for that 2-hour window, the 1-2-3 rule."),
    S(1, 2, "Alternate minimums", "An alternate has only a nonprecision approach and no published alternate minimums. What forecast does it need at your ETA?",
      ["800-foot ceiling and 2 SM", "600-foot ceiling and 2 SM", "400-foot ceiling and 1 SM"],
      "When a procedure lists no alternate minimums, 91.169(c) uses the standard ones: 600 and 2 for a precision approach, 800 and 2 for a nonprecision approach."),
    S(1, 1, "IFR fuel", "An airplane filed IFR with an alternate must carry fuel to the destination, then the alternate, then for:",
      ["45 minutes at normal cruise", "30 minutes at normal cruise", "45 minutes at holding speed"],
      "91.167 requires fuel to the first airport of intended landing, on to the alternate, and then 45 minutes at normal cruising speed. The 30-minute figure applies to helicopters."),
    S(1, 2, "VOR check", "Your VOR equipment was last checked 35 days ago and has no approved maintenance program. May you navigate IFR by VOR?",
      ["No, it must be within 30 days", "Yes, a check is good for 60 days", "Yes, if the VOR identifier is heard"],
      "91.171 requires the VOR equipment to have been operationally checked within the preceding 30 days, unless it is maintained under an approved procedure. A 35-day-old check does not count."),
    S(1, 2, "Altimeter inspection", "To fly IFR in controlled airspace, the static system and altimeter must have been tested within the preceding:",
      ["24 calendar months", "12 calendar months", "6 calendar months"],
      "91.411 requires the static system, each altimeter and the altitude reporting system to be tested and inspected within the preceding 24 calendar months. The 30-day interval is the VOR check."),
    S(1, 2, "IFR equipment", "Which item does 91.205 require for IFR flight but not for day VFR?",
      ["Rate-of-turn indicator", "Magnetic direction indicator", "Manifold pressure gauge"],
      "Day VFR already needs a magnetic direction indicator and, for altitude engines, a manifold pressure gauge. IFR adds a rate-of-turn indicator, slip-skid indicator, sensitive altimeter, clock, attitude and heading gyros and adequate electrical power."),
    S(1, 3, "Logging approaches", "When logging approaches for 61.57 currency, what must the logbook record for each approach?",
      ["Its location and type", "Its decision altitude or MDA", "The ATC facility that cleared it"],
      "61.51(g)(3) requires the location and type of each instrument approach and, when one was required, the safety pilot's name."),
    # ---------- Practice Test 2 ----------
    S(2, 3, "Instrument proficiency check", "A pilot last met the 61.57(c) tasks in March and has done none since. From what date is an IPC the only way back?",
      ["April 1 of the next year", "October 1 of the same year", "March 31 of the next year"],
      "Currency from March runs through September 30. During the next 6 calendar months (to March 31) the pilot can still log the tasks with a safety pilot or instructor. From April 1 an instrument proficiency check is required."),
    S(2, 2, "Alternate minimums", "Your planned alternate has only an ILS and lists no special alternate minimums. What forecast must it show?",
      ["600-foot ceiling and 2 SM", "800-foot ceiling and 2 SM", "1,000-foot ceiling and 3 SM"],
      "With no published alternate minimums, 91.169(c) sets 600 feet and 2 SM for a precision approach and 800 feet and 2 SM for a nonprecision approach."),
    S(2, 3, "Alternate without approach", "An alternate airport has no instrument approach. When may you list it?",
      ["When descent from the MEA can be made in basic VFR", "When its ceiling is forecast at 2,000 feet or more", "When a nearby airport within 5 miles has an ILS"],
      "Under 91.169(c)(2), an alternate with no approach procedure needs weather that allows descent from the MEA, approach and landing under basic VFR."),
    S(2, 2, "VOR check", "No VOT or ground checkpoint exists, so you use a designated airborne checkpoint. What error is allowed?",
      ["Plus or minus 6 degrees", "Plus or minus 4 degrees", "Plus or minus 10 degrees"],
      "91.171(b)(3) allows plus or minus 6 degrees over an airborne checkpoint. Ground checks with a VOT or surface checkpoint allow 4 degrees."),
    S(2, 2, "Dual VOR check", "Two independent VOR receivers are tuned to one station. What is the largest difference allowed?",
      ["4 degrees", "6 degrees", "8 degrees"],
      "91.171(c) lets a pilot check one VOR system against the other; the two indicated bearings may differ by no more than 4 degrees."),
    S(2, 2, "Static system", "A mechanic opened the static system to replace a line, then closed it. What is needed before IFR in controlled airspace?",
      ["A static system test", "An operational check of the VOR", "A new transponder inspection"],
      "91.411(a)(2) requires a test and inspection after any opening and closing of the static system, except for drains and the alternate static valve."),
    S(2, 1, "Safety pilot", "A pilot practises under a view-limiting device. What must the safety pilot hold at minimum?",
      ["Private certificate, same category and class", "Current instrument rating in that airplane", "Flight instructor certificate"],
      "91.109(c) requires a safety pilot with at least a private certificate with the right category and class ratings, adequate vision, and an airplane with dual controls."),
    S(2, 3, "Instrument rating experience", "Of the 40 hours of instrument time for the instrument-airplane rating, how many must come from an authorized instructor?",
      ["15", "10", "5"],
      "61.65(d)(2) requires 40 hours of actual or simulated instrument time, of which 15 hours must be from an authorized instructor with an instrument-airplane rating."),
    # ---------- Drill only ----------
    S(0, 1, "Instrument rating required", "When must a private pilot hold an instrument rating to act as PIC?",
      ["Under IFR or in Class A airspace", "At night above 10,000 feet MSL", "Over water beyond gliding distance"],
      "61.3(e) requires an instrument rating to act as PIC under IFR, in weather below VFR minimums, or in Class A airspace."),
    S(0, 2, "Instrument rating experience", "The instrument cross-country flown with an instructor for the rating must be at least:",
      ["250 NM, three kinds of approaches", "150 NM, two kinds of approaches", "250 NM, one approach at the end"],
      "61.65(d)(2)(ii) requires one IFR cross-country of 250 NM along airways or ATC routing, an approach at each airport, and three different kinds of approaches."),
    S(0, 2, "Instrument rating experience", "The 3 hours of instrument training before the practical test must fall within what time?",
      ["2 calendar months", "60 days", "6 calendar months"],
      "61.65(d)(2)(i) requires 3 hours of instrument flight training with an authorized instructor within 2 calendar months before the practical test."),
    S(0, 2, "Training devices", "May the six approaches, holding and tracking for 61.57(c) be flown in an aviation training device?",
      ["Yes, in a device for that category", "No, only an airplane counts", "Only with an instructor in the device"],
      "61.57(c)(2) allows a full flight simulator, flight training device or aviation training device representing the category, in any mix with flights in the aircraft."),
    S(0, 1, "Preflight action", "Under 91.103, which item must a pilot learn about before any IFR flight?",
      ["Alternatives if it can't be completed", "The en route center's sector frequencies", "The tower's hours at every airport en route"],
      "For IFR flights and flights away from the airport, 91.103 requires weather reports and forecasts, fuel requirements, alternatives if the flight cannot be completed, and known traffic delays."),
    S(0, 2, "Malfunction report", "Which item must a 91.187 report of failed navigation equipment include?",
      ["How far IFR capability is impaired", "The time the failure first began", "Who last serviced the failed equipment"],
      "91.187 requires the aircraft identification, equipment affected, degree to which IFR capability is impaired, and the nature and extent of assistance desired from ATC."),
    S(0, 3, "Emergency priority", "ATC gave you priority in an emergency, though you broke no rule. When is a written report due within 48 hours?",
      ["When ATC asks for one", "Always, to the FSDO", "Only if you declared Mayday"],
      "91.123(d) requires a detailed report within 48 hours to the ATC facility manager only if ATC requests it."),
    S(0, 2, "Supplemental oxygen", "Between 12,500 and 14,000 feet cabin altitude, the required crew must use oxygen for time at those altitudes over:",
      ["30 minutes", "45 minutes", "60 minutes"],
      "91.211(a)(1): above 12,500 up to 14,000 feet MSL, the required crew must use oxygen for any part of the flight there longer than 30 minutes. Above 14,000 feet it is the entire time."),
    S(0, 3, "Altimeter inspection", "An altimeter was tested only to 12,000 feet. What does 91.411 then limit?",
      ["IFR in controlled airspace above it", "Any flight above 12,000 feet at night", "VFR above 12,000 feet in Class E"],
      "91.411(d) bars IFR operation in controlled airspace above the maximum altitude to which the altimeters and altitude reporting system were tested."),
    S(0, 2, "Transponder inspection", "How often must the transponder be tested and inspected under 91.413?",
      ["Every 24 calendar months", "Every 12 calendar months", "At each annual inspection"],
      "91.413 requires the ATC transponder to have been tested and inspected within the preceding 24 calendar months, and after any work that could cause a data correspondence error."),
]
